function mg_crm_scheduled_uuid(): string { $b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4)); }
function mg_crm_scheduled_json(mixed $raw): array { if(is_array($raw))return $raw;$raw=trim((string)$raw);if($raw==='')return [];try{$d=json_decode($raw,true,512,JSON_THROW_ON_ERROR);return is_array($d)?$d:[];}catch(Throwable){return [];} }
function mg_crm_scheduled_ready(PDO $pdo): bool { try{$st=$pdo->query("SHOW TABLES LIKE 'crm_scheduled_actions'");return (bool)$st->fetchColumn();}catch(Throwable){return false;} }
function mg_crm_scheduled_time(mixed $value): string { $raw=trim((string)$value);if($raw==='')mg_fail('Scheduled time is required.',422);$raw=str_replace('T',' ',$raw);if(preg_match('/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}$/',$raw))$raw.=':00';$ts=strtotime($raw);if($ts===false)mg_fail('Invalid scheduled time.',422);if($ts<time()-60)mg_fail('Scheduled time must be in the future.',422);return date('Y-m-d H:i:s',$ts); }
function mg_crm_scheduled_idempotency(mixed $value,string $prefix,int $merchantId,array $parts=[]): string { $key=trim((string)$value);if($key==='')$key=substr($prefix.':'.hash('sha256',$merchantId.'|'.implode('|',array_map('strval',$parts)).'|'.microtime(true)),0,190);if(mb_strlen($key)>190||preg_match('/^[A-Za-z0-9:._-]+$/',$key)!==1)mg_fail('Invalid scheduled action request.',422);return $key; }
function mg_crm_scheduled_summary_seed(): array { return ['selected'=>0,'scheduled'=>0,'processed'=>0,'issued'=>0,'invited'=>0,'sent'=>0,'skipped'=>0,'failed'=>0,'duplicates'=>0]; }
function mg_crm_scheduled_find_user(PDO $pdo,string $email,?int $sourceUserId): ?int { if($sourceUserId&&$sourceUserId>0)return $sourceUserId;$st=$pdo->prepare("SELECT id FROM users WHERE LOWER(email)=LOWER(?) AND status='active' LIMIT 1");$st->execute([$email]);$id=(int)($st->fetchColumn()?:0);return $id>0?$id:null; }
function mg_crm_scheduled_campaign_label(string $type): string { return match($type){'customer_refund'=>'Customer Refund','referral_reward'=>'Referral Reward','newsletter_signup'=>'Newsletter Signup','contest_giveaway'=>'Contest / Giveaway',default=>ucwords(str_replace('_',' ',$type))}; }
function mg_crm_scheduled_reward_expiry(array $campaign): ?string { $r=(string)($campaign['expiration_rule']??'none');if(($r==='fixed_date'||$r==='event_date')&&!empty($campaign['expires_at']))return (string)$campaign['expires_at'];if($r==='after_issue'&&!empty($campaign['expiration_days']))return date('Y-m-d H:i:s',time()+((int)$campaign['expiration_days']*86400));return null; }
function mg_crm_scheduled_campaign_event(PDO $pdo,array $campaign,?int $walletItemId,?int $contactId,string $type,array $context=[]): void { $pdo->prepare('INSERT INTO campaign_events (public_id,merchant_user_id,campaign_id,wallet_item_id,contact_id,event_type,event_context_json,created_at) VALUES (?,?,?,?,?,?,?,NOW())')->execute([mg_crm_scheduled_uuid(),(int)$campaign['merchant_user_id'],(int)$campaign['id'],$walletItemId,$contactId,$type,json_encode($context,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);mg_campaign_followup_schedule($pdo,['merchant_user_id'=>(int)$campaign['merchant_user_id'],'campaign_id'=>(int)$campaign['id'],'contact_id'=>$contactId,'wallet_item_id'=>$walletItemId,'trigger_event'=>$type,'context'=>$context]); }
function mg_crm_scheduled_campaign_bridge(PDO $pdo,array $campaign,array $contact,int $walletDbId,string $walletPublicId,int $userId,?string $expiresAt,string $note): ?array { return mg_zero_reward_issue_from_wallet($pdo,['merchant_user_id'=>(int)$campaign['merchant_user_id'],'recipient_user_id'=>$userId,'recipient_external_id'=>(string)$contact['public_id'],'recipient_name'=>(string)($contact['name']??''),'wallet_item_db_id'=>$walletDbId,'wallet_item_public_id'=>$walletPublicId,'campaign_public_id'=>(string)$campaign['public_id'],'reward_template_public_id'=>(string)$campaign['reward_template_public_id'],'source_type'=>'crm_scheduled_campaign_reward','source_reference'=>$walletPublicId,'source_line_reference'=>(string)$contact['public_id'],'title'=>(string)$campaign['reward_template_title'],'description'=>$campaign['reward_template_description']??null,'currency'=>(string)($campaign['currency']??'USD'),'display_value_cents'=>(int)($campaign['value_amount_cents']??0),'expires_at'=>$expiresAt,'redemption_instructions'=>$campaign['redemption_instructions']??null,'terms'=>['campaign_type'=>(string)$campaign['campaign_type'],'note'=>$note,'scheduled_action'=>true]]); }
function mg_crm_scheduled_load_campaign(PDO $pdo,int $merchantId,string $campaignRef,bool $forUpdate=true): array { $sql="SELECT c.*,rt.id reward_template_db_id,rt.public_id reward_template_public_id,rt.title reward_template_title,rt.description reward_template_description,rt.redemption_instructions,rt.value_amount_cents,rt.currency,rt.expiration_rule,rt.expiration_days,rt.expires_at,rt.quantity_limit reward_template_quantity_limit,rt.issued_count reward_template_issued_count,rt.per_user_limit reward_template_per_user_limit,rt.status reward_template_status FROM campaigns c INNER JOIN reward_templates rt ON rt.id=c.reward_template_id WHERE c.public_id=? AND c.merchant_user_id=? LIMIT 1".($forUpdate?' FOR UPDATE':'');$st=$pdo->prepare($sql);$st->execute([$campaignRef,$merchantId]);$c=$st->fetch(PDO::FETCH_ASSOC);if(!$c)throw new RuntimeException('Eligible reward-backed campaign not found.');return $c; }
function mg_crm_scheduled_campaign_ready(array $campaign): void { $label=mg_crm_scheduled_campaign_label((string)$campaign['campaign_type']);if((string)$campaign['status']!=='active'||(string)$campaign['reward_template_status']!=='active')throw new RuntimeException($label.' campaign must be active with an active reward assigned.');$now=time();if(!empty($campaign['starts_at'])&&strtotime((string)$campaign['starts_at'])>$now)throw new RuntimeException($label.' campaign has not started yet.');if(!empty($campaign['ends_at'])&&strtotime((string)$campaign['ends_at'])<$now)throw new RuntimeException($label.' campaign has ended.');if($campaign['quantity_limit']!==null&&(int)$campaign['issued_count']>=(int)$campaign['quantity_limit'])throw new RuntimeException($label.' campaign inventory is unavailable.');if($campaign['reward_template_quantity_limit']!==null&&(int)$campaign['reward_template_issued_count']>=(int)$campaign['reward_template_quantity_limit'])throw new RuntimeException('Assigned reward inventory is unavailable.'); }
function mg_crm_scheduled_issue_campaign_reward(PDO $pdo,array $sourceContact,array $campaign,int $merchantId,string $note,string $idem,bool $allowDuplicate=false): array { mg_crm_scheduled_campaign_ready($campaign);$email=strtolower(trim((string)($sourceContact['email']??'')));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Customer email is required.');$userId=mg_crm_scheduled_find_user($pdo,$email,(int)($sourceContact['user_id']??0)?:null);if(!$userId)throw new RuntimeException('Customer account required.');$targetLookup=$pdo->prepare('SELECT * FROM campaign_contacts WHERE campaign_id=? AND email=? LIMIT 1 FOR UPDATE');$targetLookup->execute([(int)$campaign['id'],$email]);$target=$targetLookup->fetch(PDO::FETCH_ASSOC);if(!$target){$pid=mg_crm_scheduled_uuid();$meta=['campaign_type'=>(string)$campaign['campaign_type'],'source_contact_id'=>(string)$sourceContact['public_id'],'scheduled_action'=>true];$pdo->prepare('INSERT INTO campaign_contacts (public_id,merchant_user_id,campaign_id,user_id,email,phone,name,source,opt_in_status,metadata_json,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,NOW(),NOW())')->execute([$pid,$merchantId,(int)$campaign['id'],$userId,$email,$sourceContact['phone']??null,$sourceContact['name']??null,'scheduled_manual','opted_in',json_encode($meta,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]);$targetLookup->execute([(int)$campaign['id'],$email]);$target=$targetLookup->fetch(PDO::FETCH_ASSOC);}else{$pdo->prepare('UPDATE campaign_contacts SET user_id=?,phone=COALESCE(NULLIF(phone,\'\'),?),name=COALESCE(NULLIF(name,\'\'),?),updated_at=NOW() WHERE id=?')->execute([$userId,$sourceContact['phone']??null,$sourceContact['name']??null,(int)$target['id']]);$targetLookup->execute([(int)$campaign['id'],$email]);$target=$targetLookup->fetch(PDO::FETCH_ASSOC);}if(!$target)throw new RuntimeException('Campaign contact could not be prepared.');$old=$pdo->prepare("SELECT public_id FROM wallet_items WHERE merchant_user_id=? AND campaign_id=? AND source_type='manual_send' AND JSON_UNQUOTE(JSON_EXTRACT(metadata_json,'$.crm_idempotency_key'))=? LIMIT 1");$old->execute([$merchantId,(int)$campaign['id'],$idem]);$oldId=(string)($old->fetchColumn()?:'');if($oldId!=='')return ['contact_id'=>(string)$target['public_id'],'status'=>'duplicate','wallet_item_id'=>$oldId,'duplicate'=>true];if(!$allowDuplicate){$dupe=$pdo->prepare("SELECT public_id FROM wallet_items WHERE merchant_user_id=? AND contact_id=? AND campaign_id=? AND reward_template_id=? AND source_type='manual_send' AND status IN ('issued','viewed','claimed','redeemed') AND (expires_at IS NULL OR expires_at>NOW()) ORDER BY id DESC LIMIT 1");$dupe->execute([$merchantId,(int)$target['id'],(int)$campaign['id'],(int)$campaign['reward_template_db_id']]);$dupeId=(string)($dupe->fetchColumn()?:'');if($dupeId!=='')return ['contact_id'=>(string)$target['public_id'],'status'=>'skipped','reason'=>'active_duplicate','wallet_item_id'=>$dupeId,'duplicate'=>true];}mg_public_campaign_enforce_reward_limits($pdo,$campaign,$userId,$email);$expires=mg_crm_scheduled_reward_expiry($campaign);$wallet=mg_crm_scheduled_uuid();$stamp=mg_public_campaign_debit_reward_stamp($pdo,$campaign,$wallet,'crm_scheduled_campaign_reward',['contact_id'=>(string)$target['public_id'],'source_contact_id'=>(string)$sourceContact['public_id'],'email'=>$email]);$meta=['campaign_type'=>(string)$campaign['campaign_type'],'crm_send_campaign_id'=>(string)$campaign['public_id'],'crm_source_contact_id'=>(string)$sourceContact['public_id'],'reward_template_id'=>(string)$campaign['reward_template_public_id'],'note'=>$note,'crm_idempotency_key'=>$idem,'stamp_ledger_entry_id'=>$stamp['entry']['entry_id']??null,'scheduled_action'=>true];$pdo->prepare('INSERT INTO wallet_items (public_id,user_id,contact_id,merchant_user_id,reward_template_id,campaign_id,source_type,source_id,status,value_cents_snapshot,currency_snapshot,title_snapshot,metadata_json,issued_at,expires_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),?,NOW(),NOW())')->execute([$wallet,$userId,(int)$target['id'],$merchantId,(int)$campaign['reward_template_db_id'],(int)$campaign['id'],'manual_send',(string)$target['public_id'],'issued',(int)$campaign['value_amount_cents'],(string)$campaign['currency'],(string)$campaign['reward_template_title'],json_encode($meta,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$expires]);$walletDb=(int)$pdo->lastInsertId();$pdo->prepare('UPDATE campaigns SET issued_count=issued_count+1,updated_at=NOW() WHERE id=?')->execute([(int)$campaign['id']]);$pdo->prepare('UPDATE reward_templates SET issued_count=issued_count+1,updated_at=NOW() WHERE id=?')->execute([(int)$campaign['reward_template_db_id']]);$bridge=mg_crm_scheduled_campaign_bridge($pdo,$campaign,$target,$walletDb,$wallet,$userId,$expires,$note);$ctx=['wallet_item_id'=>$wallet,'campaign_type'=>(string)$campaign['campaign_type'],'campaign_type_label'=>mg_crm_scheduled_campaign_label((string)$campaign['campaign_type']),'target_campaign_id'=>(string)$campaign['public_id'],'target_contact_id'=>(string)$target['public_id'],'source_contact_id'=>(string)$sourceContact['public_id'],'reward_template_id'=>(string)$campaign['reward_template_public_id'],'pppm_bridge'=>$bridge,'stamp_ledger_entry_id'=>$stamp['entry']['entry_id']??null,'note'=>$note,'scheduled_action'=>true];mg_crm_scheduled_campaign_event($pdo,$campaign,$walletDb,(int)$target['id'],'wallet_item.issued',$ctx);mg_crm_scheduled_campaign_event($pdo,$campaign,$walletDb,(int)$target['id'],'crm.campaign_reward.sent',$ctx);mg_merchant_crm_record_event($pdo,['merchant_user_id'=>$merchantId,'campaign_id'=>(int)$campaign['id'],'campaign_type'=>(string)$campaign['campaign_type'],'event_type'=>'crm.campaign_reward.sent','source_type'=>'crm_scheduled_campaign_reward','source_public_id'=>(string)$target['public_id'],'user_id'=>$userId,'email'=>$email,'name'=>(string)($target['name']??''),'value_cents'=>(int)$campaign['value_amount_cents'],'metadata'=>['wal