function mg_crm_scheduled_result_summary(array $results): array { $s=mg_crm_scheduled_summary_seed();$s['selected']=count($results);foreach($results as $r){$st=(string)($r['status']??'');if($st==='scheduled')$s['scheduled']++;if($st==='sent')$s['sent']++;if($st==='issued')$s['issued']++;if($st==='invited')$s['invited']++;if($st==='skipped')$s['skipped']++;if($st==='failed')$s['failed']++;if(!empty($r['duplicate']))$s['duplicates']++;if(in_array($st,['sent','issued','invited','skipped','failed','duplicate'],true))$s['processed']++;}return $s; }
function mg_crm_scheduled_batch_status(array $summary): string { if((int)$summary['failed']>0)return 'needs_review';if((int)$summary['processed']>0&&(int)$summary['processed']<(int)$summary['selected'])return 'partial';if((int)$summary['processed']>=(int)$summary['selected']&&(int)$summary['selected']>0)return 'complete';return 'scheduled'; }
function mg_crm_scheduled_process_payload(PDO $pdo,array $action,array $contact,array $payload,int $merchantId): array { $type=(string)$action['action_type'];$note=(string)($payload['note']??'');$idem=(string)$action['idempotency_key'];if($type==='message'){return mg_crm_bulk_queue_message($pdo,$contact,$merchantId,(string)($payload['message']??''),$idem);}if($type==='reward_template'){if((int)($contact['user_id']??0)>0)return mg_crm_bulk_issue_direct_reward($pdo,$contact,mg_crm_bulk_template($pdo,$merchantId,(string)$payload['reward_template_id']),$merchantId,$note,$idem);return mg_crm_bulk_send_reward_invite($pdo,$contact,mg_crm_bulk_template($pdo,$merchantId,(string)$payload['reward_template_id']),$merchantId,$note,$idem);}if($type==='campaign_reward'){$campaign=mg_crm_scheduled_load_campaign($pdo,$merchantId,(string)$payload['campaign_id'],true);if((int)($contact['user_id']??0)>0){$result=mg_crm_scheduled_issue_campaign_reward($pdo,$contact,$campaign,$merchantId,$note,$idem,!empty($payload['allow_duplicate']));}else{$template=mg_crm_bulk_template($pdo,$merchantId,(string)$campaign['reward_template_public_id']);$result=mg_crm_bulk_send_reward_invite($pdo,$contact,$template,$merchantId,$note,'invite:'.$idem);}$msg=trim((string)($payload['message']??''));if(!empty($payload['send_message'])&&$msg!==''&&in_array((string)($result['status']??''),['issued','invited','duplicate'],true))$result['message']=mg_crm_bulk_queue_message($pdo,$contact,$merchantId,$msg,'message:'.$idem);return $result;}throw new RuntimeException('Unsupported scheduled action type.'); }
function mg_crm_scheduled_process_due(PDO $pdo,int $merchantId,int $limit=25): array { if(!mg_crm_scheduled_ready($pdo))throw new RuntimeException('CRM scheduled action schema is not installed.');$limit=max(1,min(100,$limit));$st=$pdo->prepare("SELECT id FROM crm_scheduled_actions WHERE merchant_user_id=? AND status='scheduled' AND scheduled_at<=NOW() ORDER BY scheduled_at ASC,id ASC LIMIT {$limit}");$st->execute([$merchantId]);$ids=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));$results=[];foreach($ids as $id){try{$pdo->beginTransaction();$rowSt=$pdo->prepare('SELECT * FROM crm_scheduled_actions WHERE id=? AND merchant_user_id=? AND status=\'scheduled\' FOR UPDATE');$rowSt->execute([$id,$merchantId]);$action=$rowSt->fetch(PDO::FETCH_ASSOC);if(!$action){$pdo->commit();continue;}$pdo->prepare('UPDATE crm_scheduled_actions SET status=\'processing\',locked_at=NOW(),attempts=attempts+1,updated_at=NOW() WHERE id=?')->execute([$id]);$contacts=mg_crm_bulk_contacts($pdo,$merchantId,[(string)($action['payload_json']? (mg_crm_scheduled_json($action['payload_json'])['contact_id']??'') : '')],true);$payload=mg_crm_scheduled_json($action['payload_json']);$contactRef=(string)($payload['contact_id']??'');if(!isset($contacts[$contactRef]))throw new RuntimeException('CRM contact not found.');$contact=$contacts[$contactRef];$result=mg_crm_scheduled_process_payload($pdo,$action,$contact,$payload,$merchantId);$status=in_array((string)($result['status']??''),['failed'],true)?'failed':'complete';$pdo->prepare('UPDATE crm_scheduled_actions SET status=?,processed_at=NOW(),result_json=?,last_error=NULL,updated_at=NOW() WHERE id=?')->execute([$status,json_encode($result,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$id]);$results[]=['action_id'=>(string)$action['public_id']]+$result;$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction()){$pdo->prepare('UPDATE crm_scheduled_actions SET status=\'failed\',failed_at=NOW(),last_error=?,result_json=?,updated_at=NOW() WHERE id=?')->execute([$e->getMessage(),json_encode(['status'=>'failed','reason'=>$e->getMessage()],JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),$id]);$pdo->commit();}$results[]=['action_id'=>(string)$id,'status'=>'failed','reason'=>$e->getMessage()];}}mg_crm_scheduled_refresh_batches($pdo,$merchantId);return ['summary'=>mg_crm_scheduled_result_summary($results),'results'=>$results]; }
function mg_crm_scheduled_refresh_batches(PDO $pdo,int $merchantId): void { $b=$pdo->prepare("SELECT b.id,b.public_id FROM crm_scheduled_action_batches b WHERE b.merchant_user_id=? AND b.status IN ('scheduled','partial','processing')");$b->execute([$merchantId]);foreach($b->fetchAll(PDO::FETCH_ASSOC) as $batch){$s=$pdo->prepare("SELECT status,result_json FROM crm_scheduled_actions WHERE batch_id=?");$s->execute([(int)$batch['id']]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$results=[];foreach($rows as $r){$j=mg_crm_scheduled_json($r['result_json']??'');$results[]=$j?:['status'=>(string)$r['status']];}$summary=mg_crm_scheduled_result_summary($results);$status=mg_crm_scheduled_batch_status($summary);$pdo->prepare('UPDATE crm_scheduled_action_batches SET status=?,processed_count=?,skipped_count=?,failed_count=?,result_summary_json=?,updated_at=NOW() WHERE id=?')->execute([$status,(int)$summary['processed'],(int)$summary['skipped'],(int)$summary['failed'],json_encode($summary,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE),(int)$batch['id']]);} }
